12	interface TimelineAddNoteProps {
13	  disabled?: boolean;
14	  message: string;
15	  reset: () => void;
16	  onChange: (event: React.ChangeEvent<HTMLTextAreaElement>) => void;
17	  onSubmit: () => void;
18	  placeholder?: string;
19	  buttonLabel?: string | React.ReactNode;
20	  label?: string;
21	  /** Draw a vertical line from the note input down to the first timeline item. */
22	  showTimelineConnector?: boolean;
23	}
24	
25	export const TimelineAddNote = ({
26	  message,
27	  onChange,
28	  onSubmit,
29	  reset,
30	  disabled,
31	  placeholder,
32	  buttonLabel,
33	  label,
34	  showTimelineConnector = false,
35	}: TimelineAddNoteProps) => {
36	  const intl = useIntl();
37	  const [isFocused, setIsFocused] = useState(false);
38	  const isMessageEmpty = message.trim().length === 0;
39	  const canSubmit = !disabled && !isMessageEmpty;
40	
41	  const submit = () => {
42	    if (canSubmit) {
43	      reset();
44	      onSubmit();
45	    }
46	  };
47	
48	  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
49	    if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
50	      e.preventDefault();
51	      submit();
52	    }
53	  };
54	
55	  // Macaw Textarea keeps ::placeholder transparent until focus (floating-label pattern).
56	  // Without a label the field looks empty — fall back so the empty state always has a hint.
57	  const defaultNoteHint = intl.formatMessage({
58	    id: "3evXPj",
59	    defaultMessage: "Leave your note here...",
60	  });
61	
62	  const defaultButtonLabel = (
63	    <FormattedMessage id="v/1VA6" defaultMessage="Send" description="add order note, button" />
64	  );
65	
66	  return (
67	    <Box>
68	      <Box position="relative">
69	        <Textarea
70	          disabled={disabled}
71	          label={label ?? defaultNoteHint}
72	          placeholder={placeholder ?? defaultNoteHint}
73	          onChange={onChange}
74	          onKeyDown={handleKeyDown}
75	          onFocus={() => setIsFocused(true)}
76	          onBlur={() => setIsFocused(false)}
77	          value={message}
78	          name="message"
79	          width="100%"
80	          rows={3}
81	        />
82	        <Box position="absolute" __bottom="8px" __right="8px">
83	          <SendFormKeyboardShortcutHint visible={isFocused} />
84	        </Box>
85	      </Box>
86	      {/*
87	        Stem lives here (not inside the textarea wrapper) so it isn't clipped by
88	        macaw field overflow. Top of this box = note input bottom border.
89	        paddingBottom replaces the old marginBottom so the stem can paint through it.
90	      */}
91	      <Box position="relative" paddingBottom={6} overflow="visible">
92	        {showTimelineConnector ? (
93	          <TimelineStem top={0} bottom="-16px" data-test-id="timeline-note-connector" />
94	        ) : null}
95	        <Box display="flex" justifyContent="flex-end" alignItems="center" marginTop={2}>
96	          <Button disabled={!canSubmit} onClick={submit} variant="secondary" type="button">
97	            {buttonLabel ?? defaultButtonLabel}
98	          </Button>
99	        </Box>
100	      </Box>
101	    </Box>
102	  );
103	};
